package model;

/**
 * Represents one row of the "students" table.
 */
public class Student {

    private int studentId;
    private String name;
    private String email;
    private String password; // stores the SHA-256 hash, never the plain password
    private String phone;
    private String department;
    private String rollNumber;

    public Student() {
    }

    // Used when registering a new student (the ID is generated by MySQL).
    public Student(String name, String email, String password, String phone,
                   String department, String rollNumber) {
        this.name = name;
        this.email = email;
        this.password = password;
        this.phone = phone;
        this.department = department;
        this.rollNumber = rollNumber;
    }

    // Used when reading a student from the database.
    public Student(int studentId, String name, String email, String password, String phone,
                   String department, String rollNumber) {
        this(name, email, password, phone, department, rollNumber);
        this.studentId = studentId;
    }

    public int getStudentId() {
        return studentId;
    }

    public void setStudentId(int studentId) {
        this.studentId = studentId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPassword() {
        return password;
    }

    public void setPassword(String password) {
        this.password = password;
    }

    public String getPhone() {
        return phone;
    }

    public void setPhone(String phone) {
        this.phone = phone;
    }

    public String getDepartment() {
        return department;
    }

    public void setDepartment(String department) {
        this.department = department;
    }

    public String getRollNumber() {
        return rollNumber;
    }

    public void setRollNumber(String rollNumber) {
        this.rollNumber = rollNumber;
    }
}
